import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;import java.math.BigInteger;
public class ZNov04GroundEntryOracleV2 extends GhidraScript{
 static final long RET=0x12345000L,S=0x7fff0000L,U=0x5e30c8L,R=0x60ec00L,B=0x70000000L,CP=B+1024;
 long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}
 void back(EmulatorHelper e)throws Exception{long sp=e.readRegister("ESP").longValue(),ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<1024;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{e.writeMemory(toAddr(U),new byte[21*192]);e.writeMemory(toAddr(R),new byte[72]);e.writeMemory(toAddr(B),new byte[2048]);put(e,0x632194,4,R);put(e,B+0x20,4,CP);put(e,CP+8,1,s/19%3);put(e,0x499f38,1,20);int tx=500+(s/16%9-4)*40,ty=600+(s/144%7-3)*40;put(e,U+44,2,500);put(e,U+46,2,600);put(e,U+0x50,4,3456);put(e,U+0x54,2,tx);put(e,U+0x56,2,ty);put(e,U+0x42,2,1234+s);put(e,U+0x44,2,-2000+s*5);put(e,U+0x5e,1,new int[]{-1,0,1}[s/8%3]);put(e,U+0x5f,1,0);put(e,U+0x31,1,4+s/3%4);put(e,U+0x7c,1,new int[]{0,1,2,3,4,15,16,18}[s%8]);put(e,U+0x5c,1,-5);put(e,U+0x35,1,8);put(e,U+0x32,2,s*11);put(e,U+0x3c,1,s*13);put(e,U+0x68,1,s*17);put(e,U+0x39,1,s%8);put(e,U+4,1,new int[]{-128,0,30,60,127}[s/8%5]);put(e,U+0x99,1,s/11%2);put(e,R+9,1,s*7);put(e,R+0x3a,1,5);put(e,R+0x2c,2,3456);put(e,R+0x2e,2,tx);put(e,R+0x30,2,ty);
 for(int i=0;i<=20;i++){put(e,R+19+i,1,i);if(i==0)continue;long p=U+i*192;put(e,p+0x31,1,(s+i*7)&0x38);put(e,p+0x35,1,new int[]{0,1,7,8}[((s+i)/7)%4]);put(e,p+0x99,1,(s+i)%5==0?1:0);put(e,p+0x5c,1,3);put(e,p+0x50,4,100+i);put(e,p+0x54,2,222+i);put(e,p+0x56,2,333+i);put(e,p+0x32,2,444+i);put(e,p+0x3c,1,55);put(e,p+0x39,1,6);put(e,p+0x42,2,666+i);put(e,p+0x44,2,777+i);}
 for(long p:new long[]{RET,0x41c290,0x4093e0,0x43ea80,0x44a660,0x46e850,0x452500,0x453ff0,0x44cac0,0x459690,0x448250,0x4325e0,0x411b90,0x459af0,0x473264})e.setBreakpoint(toAddr(p));e.writeRegister("ESP",S);put(e,S,4,RET);e.writeRegister("ECX",U);if(!e.run(toAddr(0x44a040),null,monitor))throw new Exception(e.getLastError());int trace=0x811c9dc5,n=0;while(e.readRegister("EIP").longValue()!=RET){if(++n>20)throw new Exception("too many stops "+s);long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();if(pc==0x473264){double v=Double.longBitsToDouble(e.readRegister("XMM0").longValue());e.writeRegister("XMM0",BigInteger.valueOf(Double.doubleToRawLongBits(Math.sqrt(v))));back(e);continue;}int code=0;
 if(pc==0x41c290){boolean ray=read(e,0x4a69f7,1)!=0;code=ray?7:1;int hit=s%7==0?1:0;e.writeRegister("EAX",hit);if(hit!=0)put(e,read(e,sp+4,4),4,B);}else if(pc==0x4093e0){code=2;e.writeRegister("EAX",s%5==0?1:0);}else if(pc==0x43ea80){code=3;e.writeRegister("EAX",s%5==1?1:0);}else if(pc==0x44a660){code=4;e.writeRegister("EAX",s%4);}else if(pc==0x46e850){code=5;}else if(pc==0x452500){code=6;put(e,U+0x31,1,read(e,U+0x31,1)&~32);}else if(pc==0x453ff0){code=8;}else if(pc==0x44cac0){code=9;put(e,U+0x35,1,1);put(e,U+0x32,2,1);put(e,U+0x3c,1,3);}else if(pc==0x459690){code=10;put(e,U+0x35,1,42);put(e,U+0x32,2,0);}else if(pc==0x448250){code=11;put(e,U+0x35,1,8);put(e,U+0x32,2,100);put(e,U+0x3c,1,-7);put(e,U+0x68,1,31);}else if(pc==0x4325e0){code=12;e.writeRegister("EAX",s%3==0?1:0);}else if(pc==0x411b90){code=13;e.writeRegister("EAX",s/13%2);}else if(pc==0x459af0){code=14;e.writeRegister("EAX",s%8);}else throw new Exception("Unexpectedstop");trace=(trace^code)*16777619;back(e);}
 int hash=0x811c9dc5;for(int i=0;i<=20;i++){long p=U+i*192;for(int[]f:new int[][]{{0x5c,1},{0x35,1},{0x32,2},{0x3c,1},{0x68,1},{0x39,1},{0x50,4},{0x54,2},{0x56,2},{0x42,2},{0x44,2},{0x31,1}}){long v=read(e,p+f[0],f[1]);if(f[1]==2)v=(short)v;else if(f[1]==4)v=(int)v;else if(f[0]==0x5c||f[0]==0x3c||f[0]==0x68)v=(byte)v;hash=(hash^(int)v)*16777619;}}
 out.println("{\"scenario\":"+s+",\"phase\":"+read(e,U+0x35,1)+",\"order\":"+(byte)read(e,U+0x5c,1)+",\"frame\":"+(short)read(e,U+0x32,2)+",\"timer\":"+(byte)read(e,U+0x3c,1)+",\"counter\":"+(byte)read(e,U+0x68,1)+",\"heading\":"+read(e,U+0x39,1)+",\"g9\":"+read(e,R+9,1)+",\"trace\":"+(trace&0xffffffffL)+",\"roster\":"+(hash&0xffffffffL)+"}");
 }finally{e.dispose();}}}}
}
